#!/usr/bin/env bash
# Generates the GitHub Release body for ai-engkit.
#
# Usage: release-body.sh <TAG> <FOOTER> [CRITICAL_COUNT]
#
#   TAG            release tag, e.g. v1.11.4
#   FOOTER         italic footer text, e.g. "Generated by GitHub Actions"
#   CRITICAL_COUNT number of critical findings from the vulnerability scan job.
#   HIGH_COUNT, MEDIUM_COUNT, and LOW_COUNT are supplied through the environment.
#
# The Changes section prefers the curated docs/CHANGELOG.md section for this
# version; falls back to raw `git log` when the section does not exist yet
# (e.g. auto-tagged dependency updates that have not staged a CHANGELOG entry).
# Appends a `body` multi-line output to $GITHUB_OUTPUT.
set -euo pipefail

TAG="$1"
FOOTER="$2"
CRITICAL_COUNT="${3:-}"
HIGH_COUNT="${HIGH_COUNT:-}"
MEDIUM_COUNT="${MEDIUM_COUNT:-}"
LOW_COUNT="${LOW_COUNT:-}"

VERSION_NO_V="${TAG#v}"

# Previous stable tag on THIS release line (same major as TAG). ai-engkit keeps
# parallel v1.* (main) and v2.* lines, so a global "highest tag" lookup picks the
# other line's tag (a v1.21.1 release wrongly resolved v2.0.2). See
# .github/scripts/release-line-tag.sh.
_SCRIPT_DIR="$(cd "$(dirname "${BASH_SOURCE[0]}")" && pwd)"
PREV_TAG="$(bash "${_SCRIPT_DIR}/release-line-tag.sh" "${TAG}" || true)"

if [ -z "$PREV_TAG" ]; then
  SINCE_TAG="first release"
else
  SINCE_TAG="${PREV_TAG}"
fi

# Prefer the curated CHANGELOG section for this version.
CHANGELOG=""
if [ -f docs/CHANGELOG.md ]; then
  CHANGELOG=$(awk -v v="$VERSION_NO_V" '
    index($0, "## [" v "] - ") == 1 {found=1; next}
    found && /^## \[/ {exit}
    found {print}
  ' docs/CHANGELOG.md || true)
fi

# Fall back to raw git log when the CHANGELOG section is missing.
if [ -z "$CHANGELOG" ]; then
  if [ -z "$PREV_TAG" ]; then
    CHANGELOG=$(git log --oneline --no-merges | head -50 || true)
  else
    CHANGELOG=$(git log "${PREV_TAG}..HEAD" --oneline --no-merges | head -50 || true)
  fi
fi

{
  echo 'body<<RELEASE_BODY_EOF'
  echo '## Docker Image'
  echo ''
  echo '```bash'
  echo "docker pull ghcr.io/${GITHUB_REPOSITORY,,}:${TAG}"
  echo '```'
  echo ''
  echo '## Quick Start'
  echo ''
  echo '```bash'
  echo 'cp .env.example .env'
  echo 'docker compose up -d'
  echo '```'
  echo ''
  echo "## Changes (since ${SINCE_TAG})"
  echo ''
  echo "$CHANGELOG"
  echo ''
  echo '## Test Results'
  echo ''
  echo '| Job | Status |'
  echo '|-----|--------|'
  echo '| Integration Tests | ✅ Passed |'
  if [ -z "$CRITICAL_COUNT" ]; then
    echo '| Vulnerability Scan | ⚪ Scan not run |'
  else
    echo '| Vulnerability Scan | ✅ No new Critical/High findings |'
    echo ''
    echo '### Vulnerability findings by severity'
    echo ''
    echo '| Severity | Findings |'
    echo '|----------|---------:|'
    echo "| Critical | ${CRITICAL_COUNT} |"
    echo "| High | ${HIGH_COUNT:-0} |"
    echo "| Medium | ${MEDIUM_COUNT:-0} |"
    echo "| Low | ${LOW_COUNT:-0} |"
  fi
  echo ''
  echo '---'
  echo "*${FOOTER}*"
  echo 'RELEASE_BODY_EOF'
} >> "$GITHUB_OUTPUT"
